```sql
SELECT o.id, o.name, o.board_mode FROM objects o JOIN workspaces w ON o.workspace_id = w.id JOIN groups g ON w.group_id = g.id WHERE g.name = 'Engineering' AND o.type = 'whiteboard';
```

```sql
SELECT o.id, o.name, o.size, o.hash FROM objects o WHERE o.type = 'file' ORDER BY o.created_at DESC;
```

```sql
SELECT w.id, w.name, g.name as group_name FROM workspaces w JOIN groups g ON w.group_id = g.id ORDER BY g.name, w.name;
```

```sql
SELECT o.id, o.name, COUNT(we.id) as element_count FROM objects o JOIN whiteboard_elements we ON we.board_id = o.id GROUP BY o.id, o.name HAVING COUNT(we.id) > 5 ORDER BY element_count DESC;
```

```sql
SELECT DISTINCT o.id, o.name FROM objects o JOIN notebook_cells nc ON nc.board_id = o.id WHERE LOWER(nc.content) LIKE '%sales%';
```

```sql
SELECT DISTINCT o.id, o.name FROM objects o JOIN notebook_cells nc ON nc.board_id = o.id WHERE nc.cell_type = 'mermaid';
```

```sql
SELECT id, name, icon, color FROM groups ORDER BY name;
```

```sql
SELECT o.id, o.name, o.size FROM objects o WHERE o.type = 'file' AND o.size > 1000000 ORDER BY o.size DESC;
```

```sql
SELECT o.id, o.name, o.size, o.hash FROM objects o WHERE o.type = 'file' ORDER BY o.created_at DESC;
```

```sql
